+import dev.langchain4j.model.embedding.EmbeddingModel;
+import dev.langchain4j.model.embedding.TaskType;
+import dev.langchain4j.model.googleai.GoogleAiEmbeddingModel;
+import dev.langchain4j.store.embedding.EmbeddingStore;
+import dev.langchain4j.store.embedding.InMemoryEmbeddingStore;
+
+import java.time.Duration;
+import java.util.Arrays;
+import java.util.List;
+
 public class Test3 {
+
+ private static final String GEMINI_KEY_ENV = "GEMINI_KEY";
+
+ public static void main(String[] args) {
+ String apiKey = System.getenv(GEMINI_KEY_ENV);
+ if (apiKey == null || apiKey.isBlank()) {
+ System.err.println("La clé GEMINI_KEY est introuvable dans les variables d'environnement.");
+ return;
+ }
+
+ EmbeddingModel embeddingModel = GoogleAiEmbeddingModel.builder()
+ .apiKey(apiKey)
+ .modelName("text-embedding-004")
+ .taskType(TaskType.SEMANTIC_SIMILARITY)
+ .dimensions(300)
+ .timeout(Duration.ofMillis(100))
+ .build();
+
+ List<String[]> sentencePairs = Arrays.asList(
+ new String[]{"Les chats aiment dormir au soleil.", "Les félins apprécient se prélasser dans la lumière."},
+ new String[]{"Je vais acheter du pain à la boulangerie.", "Je suis en retard pour la réunion."},
+ new String[]{"Le ciel est bleu aujourd'hui.", "Aujourd'hui, le ciel paraît dégagé et azur."},
+ new String[]{"Il pleut beaucoup dans cette région.", "Cette région est très ensoleillée."}
+ );
+
+ EmbeddingStore<Embedding> embeddingStore = new InMemoryEmbeddingStore<>();
+
+ for (int i = 0; i < sentencePairs.size(); i++) {
+ String[] pair = sentencePairs.get(i);
+ List<Embedding> embeddings = embeddingModel.embedAll(Arrays.asList(pair[0], pair[1])).content();
+ Embedding firstEmbedding = embeddings.get(0);
+ Embedding secondEmbedding = embeddings.get(1);
+
+ embeddingStore.add(firstEmbedding);
+ embeddingStore.add(secondEmbedding);
+
+ double cosineSimilarity = cosineSimilarity(firstEmbedding, secondEmbedding);
+
+ System.out.printf("Paire %d:%n", i + 1);
+ System.out.printf("\tPhrase A: %s%n", pair[0]);
+ System.out.printf("\tPhrase B: %s%n", pair[1]);
+ System.out.printf("\tSimilarité cosinus: %.4f%n%n", cosineSimilarity);
+ }
+
+ List<String> queries = Arrays.asList(
+ "Les chats aiment la chaleur du soleil",
+ "Il faut que je me dépêche pour la réunion",
+ "Le temps est vraiment couvert aujourd'hui"
+ );
+
+ for (String query : queries) {
+ Embedding queryEmbedding = embeddingModel.embed(query).content();
+ EmbeddingMatchResult<Embedding> matchResult = embeddingStore.findRelevant(queryEmbedding, 2);
+
+ System.out.printf("Requête: %s%n", query);
+ for (EmbeddingMatch<Embedding> match : matchResult.matches()) {
+ System.out.printf("\tSimilarité: %.4f%n", match.score());
+ }
+ System.out.println();
+ }
+ }
+
+ private static double cosineSimilarity(Embedding embeddingA, Embedding embeddingB) {
+ List<Double> vectorA = embeddingA.vectorAsList();
+ List<Double> vectorB = embeddingB.vectorAsList();
+
+ double dotProduct = 0.0;
+ double magnitudeA = 0.0;
+ double magnitudeB = 0.0;
+
+ for (int i = 0; i < vectorA.size(); i++) {
+ double valueA = vectorA.get(i);
+ double valueB = vectorB.get(i);
+
+ dotProduct += valueA * valueB;
+ magnitudeA += valueA * valueA;
+ magnitudeB += valueB * valueB;
+ }
+
+ magnitudeA = Math.sqrt(magnitudeA);
+ magnitudeB = Math.sqrt(magnitudeB);
+
+ if (magnitudeA == 0.0 || magnitudeB == 0.0) {
+ return 0.0;
+ }
+
+ return dotProduct / (magnitudeA * magnitudeB);
+ }
