import dev.langchain4j.data.document.Document;
import dev.langchain4j.data.document.DocumentParser;
import dev.langchain4j.data.document.DocumentSplitter;
import dev.langchain4j.data.document.loader.FileSystemDocumentLoader;
import dev.langchain4j.data.document.parser.apache.pdfbox.ApachePdfBoxDocumentParser;
import dev.langchain4j.data.document.splitter.DocumentSplitters;
import dev.langchain4j.data.embedding.Embedding;
import dev.langchain4j.data.segment.TextSegment;
import dev.langchain4j.memory.chat.MessageWindowChatMemory;
import dev.langchain4j.model.chat.ChatLanguageModel;
import dev.langchain4j.model.embedding.EmbeddingModel;
import dev.langchain4j.model.embedding.onnx.allminilml6v2.AllMiniLmL6V2EmbeddingModel;
import dev.langchain4j.model.openai.OpenAiChatModel;
import dev.langchain4j.rag.content.retriever.ContentRetriever;
import dev.langchain4j.rag.content.retriever.EmbeddingStoreContentRetriever;
import dev.langchain4j.service.AiServices;
import dev.langchain4j.service.SystemMessage;
import dev.langchain4j.service.UserMessage;
import dev.langchain4j.store.embedding.EmbeddingStore;
import dev.langchain4j.store.embedding.EmbeddingStoreIngestor;
import dev.langchain4j.store.embedding.inmemory.InMemoryEmbeddingStore;

import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;
import java.util.Scanner;
public interface Assistant {

 @SystemMessage("""
 Vous êtes un assistant pédagogique expert qui répond aux questions 
 basées sur le support de cours fourni. Répondez de manière claire 
 et précise. Si vous ne trouvez pas l'information dans le contexte, 
 dites-le clairement.
 """)
 String chat(@UserMessage String userMessage);
}
public class RagPdfConversation {

 public static void main(String[] args) {
 System.out.println("=== Démarrage du système RAG avec PDF ===\n");

 // 1. Charger le fichier PDF
 String pdfFileName = "ml.pdf"; // Remplacez par le nom de votre fichier PDF
 Path documentPath = Paths.get(pdfFileName);

 System.out.println("Chargement du document : " + pdfFileName);
 DocumentParser documentParser = new ApachePdfBoxDocumentParser();
 Document document = FileSystemDocumentLoader.loadDocument(documentPath, documentParser);

 System.out.println("Document chargé avec succès !");

 // 2. Découper le document en segments
 System.out.println("Découpage du document en segments...");
 DocumentSplitter splitter = DocumentSplitters.recursive(
 300, // Taille maximale d'un segment (en tokens)
 20 // Chevauchement entre segments
 );
 List<TextSegment> segments = splitter.split(document);

 System.out.println("Document découpé en " + segments.size() + " segments.\n");

 // 3. Créer le modèle d'embedding (local, gratuit)
 System.out.println("Initialisation du modèle d'embedding...");
 EmbeddingModel embeddingModel = new AllMiniLmL6V2EmbeddingModel();

 // 4. Créer le store d'embeddings en mémoire
 EmbeddingStore<TextSegment> embeddingStore = new InMemoryEmbeddingStore<>();

 // 5. Ingérer les segments dans le store
 System.out.println("Création des embeddings et stockage...");
 EmbeddingStoreIngestor ingestor = EmbeddingStoreIngestor.builder()
 .embeddingModel(embeddingModel)
 .embeddingStore(embeddingStore)
 .build();

 ingestor.ingest(segments);
 System.out.println("Embeddings créés et stockés avec succès !\n");

 // 6. Créer le content retriever
 ContentRetriever contentRetriever = EmbeddingStoreContentRetriever.builder()
 .embeddingStore(embeddingStore)
 .embeddingModel(embeddingModel)
 .maxResults(3) // Nombre de segments pertinents à récupérer
 .minScore(0.6) // Score minimum de similarité
 .build();

 // 7. Configurer le modèle de chat (OpenAI)
 String apiKey = System.getenv("OPENAI_API_KEY"); // ou mettre votre clé directement
 if (apiKey == null || apiKey.isEmpty()) {
 System.err.println("ERREUR : La clé API OpenAI n'est pas définie !");
 System.err.println("Définissez la variable d'environnement OPENAI_API_KEY");
 return;
 }

 ChatLanguageModel chatModel = OpenAiChatModel.builder()
 .apiKey(apiKey)
 .modelName("gpt-3.5-turbo")
 .temperature(0.7)
 .build();

 // 8. Créer l'assistant avec mémoire de conversation
 System.out.println("Création de l'assistant conversationnel...");
 Assistant assistant = AiServices.builder(Assistant.class)
 .chatLanguageModel(chatModel)
 .chatMemory(MessageWindowChatMemory.withMaxMessages(10))
 .contentRetriever(contentRetriever)
 .build();

 System.out.println("Assistant prêt !\n");
 System.out.println("=".repeat(60));
 System.out.println("Vous pouvez maintenant poser vos questions.");
 System.out.println("Tapez 'quit' ou 'exit' pour quitter.");
 System.out.println("=".repeat(60));

 // 9. Boucle de conversation interactive
 Scanner scanner = new Scanner(System.in);

 while (true) {
 System.out.print("\n Vous : ");
 String userInput = scanner.nextLine().trim();

 if (userInput.equalsIgnoreCase("quit") ||
 userInput.equalsIgnoreCase("exit")) {
 System.out.println("\n Au revoir !");
 break;
 }

 if (userInput.isEmpty()) {
 continue;
 }

 try {
 System.out.println("\n Assistant : ");
 String response = assistant.chat(userInput);
 System.out.println(response);
 } catch (Exception e) {
 System.err.println("\n❌ Erreur : " + e.getMessage());
 e.printStackTrace();
 }
 }

 scanner.close();
 }
}","language":"java"},"codebaseEnabled":true},"createdAt":1762087369047,"isInternal":false,"rawContent":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"command","attrs":{"label":"fix"},"content":[{"type":"text","text":"fix: "}]},{"type":"codeBlock","attrs":{"language":"java"},"content":[{"type":"text","text":"new AllMiniLmL6V2EmbeddingModel()"}]},{"type":"text","text":"Cannot resolve symbol 'AllMiniLmL6V2EmbeddingModel'"}]}]},"autoAppliedRules":[]},{"id":"0d6a69a0-9a41-4bc9-a9ce-5b0826b1f9ab","role":"assistant","content":[{"type":"thought","text":"**Preparing to review repo rules**"},{"type":"toolCall","toolCallId":"call_CWO9QIVoaa9JsKrYwi85ko29","title":"","statusText":"File not found","status":"WARNING","isHidden":false},{"type":"toolCall","toolCallId":"call_I0wNm9laXryaT4oeuju60he7","statusText":"Viewed directory","status":"SUCCESS","context":{"files":[{"path":".","fsPath":"C:/Users/ProBook/Documents/Projets IntelliJ IDEA/AI/TPs Casablanca/tp2testkharraz"}]},"isHidden":false},{"type":"thought","text":"**Checking rules file**"},{"type":"toolCall","toolCallId":"call_ABNTxs41GsrQIQozpoFoLuQU","statusText":"Viewed directory","status":"SUCCESS","context":{"files":[{"path":".zencoder/rules","fsPath":"C:/Users/ProBook/Documents/Projets IntelliJ IDEA/AI/TPs Casablanca/tp2testkharraz/.zencoder/rules"}]},"isHidden":false},{"type":"thought","text":"**Checking missing files and dependencies**"},{"type":"toolCall","toolCallId":"call_ukux9Dkm5Zd1NIYxg4cdggAJ","statusText":"Viewed file (lines 1:69)","status":"SUCCESS","context":{"files":[{"path":"pom.xml","fsPath":"C:/Users/ProBook/Documents/Projets IntelliJ IDEA/AI/TPs Casablanca/tp2testkharraz/pom.xml"}]},"isHidden":false},{"type":"thought","text":"**Investigating missing AllMiniLmL6V2EmbeddingModel**"},{"type":"toolCall","toolCallId":"call_a28LHWH4AqoK6Z7bDetUWok1","title":"Fulltext search","statusText":"Done","status":"SUCCESS","isHidden":false},{"type":"thought","text":"**Verifying embedding import locatio