 package ma.emsi.kharraz;

+import dev.langchain4j.data.document.Document;
+import dev.langchain4j.data.document.loader.FileSystemDocumentLoader;
+import dev.langchain4j.data.embedding.Embedding;
+import dev.langchain4j.data.segment.TextSegment;
+import dev.langchain4j.memory.chat.MessageWindowChatMemory;
+import dev.langchain4j.model.chat.ChatModel;
+import dev.langchain4j.model.embedding.EmbeddingModel;
+import dev.langchain4j.model.googleai.GoogleAiGeminiChatModel;
+import dev.langchain4j.model.googleai.GoogleAiEmbeddingModel;
+import dev.langchain4j.rag.content.retriever.EmbeddingStoreContentRetriever;
+import dev.langchain4j.service.AiServices;
+import dev.langchain4j.store.embedding.EmbeddingStore;
+import dev.langchain4j.store.embedding.inmemory.InMemoryEmbeddingStore;
+
+import java.nio.file.Files;
+import java.nio.file.Path;
+import java.nio.file.Paths;
+import java.time.Duration;
+import java.util.ArrayList;
+import java.util.List;
+import java.util.Scanner;
+
 public class Test5 {
+
+ private static final String GEMINI_KEY_ENV = "GEMINI_KEY";
+ private static final String PROJECT_ROOT = "C:/Users/ProBook/Documents/Projets IntelliJ IDEA/AI/TPs Casablanca/tp2testkharraz/";
+ private static final String COURSE_PDF = PROJECT_ROOT + "ml.pdf";
+
+ private static final int CHUNK_SIZE = 900; // caractères par segment
+ private static final int CHUNK_OVERLAP = 150; // chevauchement pour préserver le contexte
+
+ interface Assistant {
+ String chat(String userMessage);
+ }
+
+ public static void main(String[] args) {
+ String apiKey = System.getenv(GEMINI_KEY_ENV);
+ if (apiKey == null || apiKey.isBlank()) {
+ System.err.println("La clé GEMINI_KEY est introuvable dans les variables d'environnement. Veuillez la définir avant de lancer le programme.");
+ return;
+ }
+
+ Path pdfPath = Paths.get(COURSE_PDF);
+ if (!Files.exists(pdfPath)) {
+ System.err.printf("Le fichier PDF attendu est introuvable : %s%n", COURSE_PDF);
+ System.err.println("Copiez le support de cours à la racine du projet, puis relancez.");
+ return;
+ }
+
+ try {
+ runAssistant(pdfPath, apiKey);
+ } catch (Exception exception) {
+ System.err.println("Une erreur est survenue pendant l'exécution du RAG : " + exception.getMessage());
+ exception.printStackTrace();
+ }
+ }
+
+ private static void runAssistant(Path pdfPath, String apiKey) {
+ Document document = FileSystemDocumentLoader.loadDocument(pdfPath);
+
+ List<TextSegment> segments = splitDocumentIntoSegments(document.text(), pdfPath.getFileName().toString());
+ System.out.printf("Document '%s' découpé en %d segments.%n", pdfPath.getFileName(), segments.size());
+
+ EmbeddingModel embeddingModel = buildEmbeddingModel(apiKey);
+ EmbeddingStore<TextSegment> embeddingStore = new InMemoryEmbeddingStore<>();
+
+ for (TextSegment segment : segments) {
+ Embedding embedding = embeddingModel.embed(segment).content();
+ embeddingStore.add(embedding, segment);
+ }
+
+ Assistant assistant = AiServices.builder(Assistant.class)
+ .chatModel(buildChatModel(apiKey))
+ .chatMemory(MessageWindowChatMemory.withMaxMessages(12))
+ .contentRetriever(EmbeddingStoreContentRetriever.builder()
+ .embeddingStore(embeddingStore)
+ .embeddingModel(embeddingModel)
+ .build())
+ .build();
+
+ runInteractiveDemo(assistant);
+ }
+
+ private static ChatModel buildChatModel(String apiKey) {
+ return GoogleAiGeminiChatModel.builder()
+ .apiKey(apiKey)
+ .modelName("gemini-2.0-flash-exp")
+ .temperature(0.3)
+ .timeout(Duration.ofSeconds(120))
+ .build();
+ }
+
+ private static EmbeddingModel buildEmbeddingModel(String apiKey) {
+ return GoogleAiEmbeddingModel.builder()
+ .apiKey(apiKey)
+ .modelName("text-embedding-004")
+ .timeout(Duration.ofSeconds(120))
+ .build();
+ }
+
+ private static List<TextSegment> splitDocumentIntoSegments(String fullText, String filename) {
+ List<TextSegment> segments = new ArrayList<>();
+ if (fullText == null || fullText.isBlank()) {
+ return segments;
+ }
+
+ int startIndex = 0;
+ int chunkIndex = 1;
+ int textLength = fullText.length();
+
+ while (startIndex < textLength) {
+ int endIndex = Math.min(startIndex + CHUNK_SIZE, textLength);
+ String chunk = fullText.substring(startIndex, endIndex).trim();
+
+ if (!chunk.isEmpty()) {
+ StringBuilder decorated = new StringBuilder();
+ decorated.append("[Document: ").append(filename)
+ .append(", segment ").append(chunkIndex)
+ .append("]\n")
+ .append(chunk);
+
+ segments.add(TextSegment.from(decorated.toString()));
+ chunkIndex++;
+ }
+
+ if (endIndex == textLength) {
+ break;
+ }
+
+ startIndex = Math.max(endIndex - CHUNK_OVERLAP, 0);
+ }
+
+ return segments;
+ }
+
+ private static void runInteractiveDemo(Assistant assistant) {
+ System.out.println("\nAssistant initialisé. Posez vos questions sur le support de cours (tapez 'exit' pour quitter).");
+
+ try (Scanner scanner = new Scanner(System.in)) {
+ while (true) {
+ System.out.print("Vous > ");
+ if (!scanner.hasNextLine()) {
+ break;
+ }
+
+ String question = scanner.nextLine().trim();
+ if (question.isEmpty()) {
+ continue;
+ }
+
+ if ("exit".equalsIgnoreCase(question) || "quit".equalsIgnoreCase(question)) {
+ System.out.println("Fin de la session. À bientôt !");
+ break;
+ }
+
+ long start = System.nanoTime();
+ String answer = assistant.chat(question);
+ long elapsed = System.nanoTime() - start;
+
+ System.out.println("Assistant > " + answer);
+ System.out.printf("(Réponse générée en %.2f secondes)%n%n", elapsed / 1_000_000_000.0);
+ }
+ }
+ }
